INSERT INTO help_article (id, module_id, chapter_no, slug, title, lang, body_html, plain_text, doc_version, updated_at, change_flag, img_count, content_hash, sort_order, is_published, permission, source) VALUES (1,1,'1.1','1-1-alapbeallitasok-beallitas-varazslo','Alapbeállítások – Beállítás varázsló','hu','<p>Az Infinity rendszer első indításakor a beállítás varázsló lépésről\r\nlépésre vezet végig az alapkonfiguráción. Az alábbiakban leírjuk, hogyan\r\nlépjünk be, és mit kell beállítani.</p>','Az Infinity rendszer első indításakor a beállítás varázsló lépésről lépésre vezet végig az alapkonfiguráción. Az alábbiakban leírjuk, hogyan lépjünk be, és mit kell beállítani.','v2026.08.26','2026-09-14','mod',0,'e1bc271644fee3e31fd93446e4ddb727',0,1,NULL,'editor');
INSERT INTO help_article (id, module_id, chapter_no, slug, title, lang, body_html, plain_text, doc_version, updated_at, change_flag, img_count, content_hash, sort_order, is_published, permission, source) VALUES (2,1,'1.2','1-2-belepes-a-rendszerbe','Belépés a rendszerbe','hu','<p>Az első belépéshez a kapott linken nyissuk meg a rendszert, majd a\nkövetkező adatokkal jelentkezzünk be:</p>\n<div class="tblwrap"><table class="erp-table">\n\n<tbody>\n<tr class="odd">\n<td><strong>Felhasználónév</strong></td>\n<td>admin</td>\n</tr>\n<tr class="even">\n<td><strong>Jelszó</strong></td>\n<td>admin123</td>\n</tr>\n</tbody>\n</table></div>\n<div class="call warn"><strong>Figyelem</strong>\n<p>Amint a varázsló segítségével létrehoztuk a saját superuser fiókot,\naz admin felhasználó automatikusan inaktívvá válik és többé nem\nhasználható belépésre.</p></div>','Az első belépéshez a kapott linken nyissuk meg a rendszert, majd a következő adatokkal jelentkezzünk be: Felhasználónév admin Jelszó admin123 Figyelem Amint a varázsló segítségével létrehoztuk a saját superuser fiókot, az admin felhasználó automatikusan inaktívvá válik és többé nem használható belépésre.','v2026.08.26','2026-08-26',NULL,0,'34abeeec788edf59',10,1,NULL,'word');
INSERT INTO help_article (id, module_id, chapter_no, slug, title, lang, body_html, plain_text, doc_version, updated_at, change_flag, img_count, content_hash, sort_order, is_published, permission, source) VALUES (3,1,'1.3','1-3-a-beallitas-varazslo-lepesei','A beállítás varázsló lépései','hu','<p>Az első bejelentkezéskor a varázsló automatikusan elindul. Később is\nbármikor elindítható a Rendszer → Egyéb → Beállítás varázsló menüponton\nkeresztül.</p>\n<div class="tblwrap"><table class="erp-table">\n\n<tbody>\n<tr class="odd">\n<td><strong>1</strong></td>\n<td><p><strong>Ország kiválasztása</strong></p>\n<p>Adjuk meg, melyik országban használjuk az Infinity-t, és hol fogunk\nszámlázni.</p></td>\n</tr>\n</tbody>\n</table></div>\n<p><img src="media/img_f3551e7da3ba.png" class="shot" loading="lazy"/></p>\n<div class="tblwrap"><table class="erp-table">\n\n<tbody>\n<tr class="odd">\n<td><strong>2</strong></td>\n<td><p><strong>Cégadatok megadása</strong></p>\n<p>Adjuk meg cégünk alapadatait (cégnév, cím, adószám, bankszámlaszám).\nE nélkül a számlázás jogszabályok alapján nem működőképes.</p></td>\n</tr>\n</tbody>\n</table></div>\n<p><img src="media/img_5164a806477f.png" class="shot" loading="lazy"/></p>\n<div class="tblwrap"><table class="erp-table">\n\n<tbody>\n<tr class="odd">\n<td><strong>3</strong></td>\n<td><p><strong>Telephelyek beállítása</strong></p>\n<p>Ha több telephelyen működünk, itt adjuk meg azokat. Egyetlen\ntelephely esetén is töltsük ki a székhely adatait.</p></td>\n</tr>\n</tbody>\n</table></div>\n<p><img src="media/img_2d5798e7ef09.png" class="shot" loading="lazy"/></p>\n<div class="tblwrap"><table class="erp-table">\n\n<tbody>\n<tr class="odd">\n<td><strong>4</strong></td>\n<td><p><strong>Raktárak megadása</strong></p>\n<p>Rendeljük hozzá a raktárakat a telephelyekhez. A készlettípusnál\nadjuk meg, hogy saját vagy bizományos készletről értékesítünk-e.\nVisszáru fogadásához külön raktárt és készlettípust alakítsunk\nki.</p></td>\n</tr>\n</tbody>\n</table></div>\n<p><img src="media/img_16e75e594cd1.png" class="shot" loading="lazy"/></p>\n<div class="tblwrap"><table class="erp-table">\n\n<tbody>\n<tr class="odd">\n<td><strong>5</strong></td>\n<td><p><strong>Pénznemek kiválasztása</strong></p>\n<p>Válasszuk ki azt a pénznemet vagy pénznemeket, amelyekben számlázni\nfogunk.</p></td>\n</tr>\n</tbody>\n</table></div>\n<p><img src="media/img_1a3a203ae5cf.png" class="shot" loading="lazy"/></p>\n<div class="tblwrap"><table class="erp-table">\n\n<tbody>\n<tr class="odd">\n<td><strong>6</strong></td>\n<td><p><strong>Számla- és nyugtatömbök</strong></p>\n<p>A rendszer alapból egy vevői és egy szállítói számlatömböt hoz létre.\nHa több számla- vagy nyugtatömbre van szükségünk, itt rögzítsük\nazokat.</p></td>\n</tr>\n</tbody>\n</table></div>\n<p><img src="media/img_ecc00c648b1f.png" class="shot" loading="lazy"/></p>\n<div class="tblwrap"><table class="erp-table">\n\n<tbody>\n<tr class="odd">\n<td><strong>7</strong></td>\n<td><p><strong>ÁFA kulcsok felvitele</strong></p>\n<p>Adjuk meg a vállalkozásunkban alkalmazott ÁFA kulcsokat. Ehhez kérjük\nkönyvelőnk segítségét.</p></td>\n</tr>\n</tbody>\n</table></div>\n<p><img src="media/img_93ea818bca8d.png" class="shot" loading="lazy"/></p>\n<div class="tblwrap"><table class="erp-table">\n\n<tbody>\n<tr class="odd">\n<td><strong>8</strong></td>\n<td><p><strong>Bankszámlák rögzítése</strong></p>\n<p>Rögzítsük bankszámlaszámainkat. Adjuk meg az IBAN számlaszámot és a\nSWIFT kódot is, ha rendelkezünk ilyennel.</p></td>\n</tr>\n</tbody>\n</table></div>\n<p><img src="media/img_2f3f4fc441ec.png" class="shot" loading="lazy"/></p>\n<div class="tblwrap"><table class="erp-table">\n\n<tbody>\n<tr class="odd">\n<td><strong>9</strong></td>\n<td><p><strong>NAV Online számla bekötése</strong></p>\n<p>A magyar jogszabályok szerint a kiállított számlákat fel kell küldeni\na NAV szerverére. Ennek elmulasztása súlyos bírsággal járhat. A\ntechnikai felhasználót a NAV online rendszerében hozzuk létre:\nhttps://onlineszamla.nav.gov.hu/felhasznalok/uj/technikai</p></td>\n</tr>\n</tbody>\n</table></div>\n<div class="call tip"><strong>✖ Kötelező beállítás</strong>\n<p>A NAV Online számla funkció beállítása jogszabályi kötelezettség. Ha\nezt kihagyjuk, a kiállított számlák nem kerülnek be a hatóság\nrendszerébe, ami bírságot vonhat maga után.</p></div>\n<p><img src="media/img_b5852dbc4414.png" class="shot" loading="lazy"/></p>\n<div class="tblwrap"><table class="erp-table">\n\n<tbody>\n<tr class="odd">\n<td><strong>10</strong></td>\n<td><p><strong>E-mail sablonok bekapcsolása</strong></p>\n<p>Kapcsoljuk be a használni kívánt e-mail sablonokat, és szükség esetén\nmódosítsuk az alapértelmezett szövegeket. A „Vissza a főoldalra" gombra\nkattintva fejezzük be az alapkonfigurálást.</p></td>\n</tr>\n</tbody>\n</table></div>\n<p><img src="media/img_865ed5caa4e6.png" class="shot" loading="lazy"/></p>\n<div class="call tip"><strong>Következő lépések</strong>\n<p>Az alapkonfiguráció után folytassuk a Felhasználók és szerepkörök\nbeállításával (Rendszer → Felhasználók), majd a partnertörzs\nfeltöltésével (Iroda → Partnerek).</p></div>','Az első bejelentkezéskor a varázsló automatikusan elindul. Később is bármikor elindítható a Rendszer → Egyéb → Beállítás varázsló menüponton keresztül. 1 Ország kiválasztása Adjuk meg, melyik országban használjuk az Infinity-t, és hol fogunk számlázni. 2 Cégadatok megadása Adjuk meg cégünk alapadatait (cégnév, cím, adószám, bankszámlaszám). E nélkül a számlázás jogszabályok alapján nem működőképes. 3 Telephelyek beállítása Ha több telephelyen működünk, itt adjuk meg azokat. Egyetlen telephely esetén is töltsük ki a székhely adatait. 4 Raktárak megadása Rendeljük hozzá a raktárakat a telephelyekhez. A készlettípusnál adjuk meg, hogy saját vagy bizományos készletről értékesítünk-e. Visszáru fogadásához külön raktárt és készlettípust alakítsunk ki. 5 Pénznemek kiválasztása Válasszuk ki azt a pénznemet vagy pénznemeket, amelyekben számlázni fogunk. 6 Számla- és nyugtatömbök A rendszer alapból egy vevői és egy szállítói számlatömböt hoz létre. Ha több számla- vagy nyugtatömbre van szükségünk, itt rögzítsük azokat. 7 ÁFA kulcsok felvitele Adjuk meg a vállalkozásunkban alkalmazott ÁFA kulcsokat. Ehhez kérjük könyvelőnk segítségét. 8 Bankszámlák rögzítése Rögzítsük bankszámlaszámainkat. Adjuk meg az IBAN számlaszámot és a SWIFT kódot is, ha rendelkezünk ilyennel. 9 NAV Online számla bekötése A magyar jogszabályok szerint a kiállított számlákat fel kell küldeni a NAV szerverére. Ennek elmulasztása súlyos bírsággal járhat. A technikai felhasználót a NAV online rendszerében hozzuk létre: https://onlineszamla.nav.gov.hu/felhasznalok/uj/technikai ✖ Kötelező beállítás A NAV Online számla funkció beállítása jogszabályi kötelezettség. Ha ezt kihagyjuk, a kiállított számlák nem kerülnek be a hatóság rendszerébe, ami bírságot vonhat maga után. 10 E-mail sablonok bekapcsolása Kapcsoljuk be a használni kívánt e-mail sablonokat, és szükség esetén módosítsuk az alapértelmezett szövegeket. A „Vissza a főoldalra" gombra kattintva fejezzük be az alapkonfigurálást. Következő lépések Az alapkonfiguráció után folytassuk a Felhasználók és szerepkörök beállításával (Rendszer → Felhasználók), majd a partnertörzs feltöltésével (Iroda → Partnerek).','v2026.08.26','2026-08-26',NULL,10,'46320a7cc9dcf034',20,1,NULL,'word');
INSERT INTO help_article (id, module_id, chapter_no, slug, title, lang, body_html, plain_text, doc_version, updated_at, change_flag, img_count, content_hash, sort_order, is_published, permission, source) VALUES (4,1,'1.4','1-4-segitseg-es-hibabejelentes','Segítség és hibabejelentés','hu','<p>Hiba vagy probléma esetén a support@orc.hu e-mail címen tudunk\nsegítséget kérni.</p>\n<div class="call warn"><strong>Hibabejelentéshez kötelezően csatolni kell</strong>\n<p>A képernyőképet a hibáról, valamint az URL-t (böngésző cím), ahol a\nprobléma jelentkezett. E nélkül a hibaelhárítás jelentősen\nlassabb.</p></div>','Hiba vagy probléma esetén a support@orc.hu e-mail címen tudunk segítséget kérni. Hibabejelentéshez kötelezően csatolni kell A képernyőképet a hibáról, valamint az URL-t (böngésző cím), ahol a probléma jelentkezett. E nélkül a hibaelhárítás jelentősen lassabb.','v2026.08.26','2026-08-26',NULL,0,'20db2aff198e31a5',30,1,NULL,'word');
INSERT INTO help_article (id, module_id, chapter_no, slug, title, lang, body_html, plain_text, doc_version, updated_at, change_flag, img_count, content_hash, sort_order, is_published, permission, source) VALUES (5,2,'2','2-a-keretrendszer','A keretrendszer','hu','<p>Az Infinity moduláris felépítésű vállalatirányítási rendszer, ahol az\negyes részterületek egymás közötti integrációjával a vállalat összes\nrészlege egységes irányítási rendszerrel dolgozhat.</p>\n<p>Mivel web alapú szoftver, bárhonnan elérhető – használatához elegendő\naz internetkapcsolat. Működtethető személyi számítógépen, tableten és\nmobiltelefonon is.</p>\n<p>Működésének eredménye egy strukturált, naprakész információkkal\nrendelkező, hatékony irányítású vállalkozás, amely a lehető legrövidebb\nreakcióidő mellett működik. Főbb jellegzetességei modulonként:</p>\n<p><strong>Adminisztráció</strong></p>\n<ul>\n<li><p>Több telephely kezelése</p></li>\n<li><p>Korlátlan számú felhasználó</p></li>\n<li><p>Egyedi felhasználói jogosultságok beállítása</p></li>\n<li><p>Feladatkezelő modul</p></li>\n<li><p>Teljes testreszabhatóság</p></li>\n</ul>\n<p><strong>Partnerkezelés</strong></p>\n<ul>\n<li><p>Egységes törzsadat kezelés</p></li>\n<li><p>Felhasználó által definiált egyedi adatok nyilvántartása</p></li>\n<li><p>Friss, aktuális partner adatok bekérése Cégjelzőből</p></li>\n<li><p>CRM integrálása minden folyamathoz</p></li>\n<li><p>Online dokumentumkezelés, papírmentes iroda megoldások</p></li>\n<li><p>Munkarendek rögzítése, szabadságok kezelése, jelenléti ívek\nnyomtatása</p></li>\n<li><p>Google űrlapok létrehozása</p></li>\n<li><p>Automata e-mail kommunikáció ügyviteli folyamatba\nintegráltan</p></li>\n</ul>\n<p><strong>CRM</strong></p>\n<ul>\n<li><p>Ügyfélminősítés egyedileg testreszabható szempontok\nalapján</p></li>\n<li><p>Automatizált, munkafolyamatokra építhető értékesítési\nfolyamat</p></li>\n<li><p>Marketing kampányok megalapozása, segítése</p></li>\n<li><p>Ügyviteli folyamatba integrált feladatkiosztás</p></li>\n<li><p>Alkalmazottak munkaidejének rögzítése, feladathoz\nrendelése</p></li>\n<li><p>Hatékony ügyfélszolgálat</p></li>\n</ul>\n<p><strong>UNAS webáruház kezelés</strong></p>\n<ul>\n<li><p>Korlátlan számú webshop párhuzamos kezelése</p></li>\n<li><p>Árucikkek feltöltése</p></li>\n<li><p>Készletváltozás azonnali, automatikus frissítése</p></li>\n<li><p>Elektronikus számlázás egy gombnyomással, vagy\nautomatikusan</p></li>\n</ul>\n<p><strong>Értékesítés</strong></p>\n<ul>\n<li><p>Árajánlat, megrendelés készítése, nyilvántartása,\nkövetése</p></li>\n<li><p>Árajánlatból megrendelés készítése, foglalások kezelése</p></li>\n<li><p>Több bizonylattömb; készlet alapú értékesítés (szállítólevéllel)\nés szolgáltatás számlák</p></li>\n<li><p>Egyedi vagy sablon alapú rögzítés</p></li>\n<li><p>Egyedi (gyári számos), sorozatszámos vonalkódok kezelése,\nvonalkód olvasó alkalmazhatósága</p></li>\n<li><p>Webes értékesítés integrálása, UNAS weboldal integrálás</p></li>\n<li><p>Vevőkártyák, utalványok, kuponok nyilvántartása,\nelfogadása</p></li>\n<li><p>Előlegbekérő vagy előlegszámla készítése, végszámlázás</p></li>\n<li><p>Fix vagy százalékos kedvezmény, egyedi árazási lehetőség\nnyugtánál és számlánál is</p></li>\n<li><p>Idegennyelvű számla kiállítás; bizonylatok rögzítése devizában,\nkorlátlan devizaszám</p></li>\n<li><p>Kiegyenlítések kezelése devizában</p></li>\n<li><p>6 alap bizonylati sablon, melyek mindegyike egyedi igényekhez\nalakítható</p></li>\n<li><p>Adóhatósági ellenőrzéshez adatszolgáltatás</p></li>\n<li><p>Értékesítési statisztikák időszakra, cikkcsoportra, outletre,\nértékesítőre szűrve</p></li>\n<li><p>Partnerek folyószámla kartonja, értékesítések fedezeti\nösszesítője</p></li>\n<li><p>Riportok lekérdezése Excelbe vagy PDF-be</p></li>\n</ul>\n<p><strong>Készletezés</strong></p>\n<ul>\n<li><p>Testre szabható, egyedi felépítésű cikktörzs, fa szerkezetű\ncikkcsoport kódok</p></li>\n<li><p>Sorozatszám kezelés (egyedi vagy nem egyedi)</p></li>\n<li><p>Minimumkészlet, minimum árrés figyelés; kép feltöltése cikkhez,\nvonalkód nyomtatása</p></li>\n<li><p>Egyedi vagy tömeges (Excel alapú) cikk létrehozás, módosítás;\ntermékvariánsok</p></li>\n<li><p>FIFO szerinti készletkezelés, tetszőleges számú telephely és\nraktár üzemeltetése</p></li>\n<li><p>Különböző tulajdonú készletek kezelése, webes foglalások\nkezelése</p></li>\n<li><p>RF adatgyűjtők, vonalkódolvasók – a manuális adatrögzítés\nkiküszöbölése</p></li>\n<li><p>Leltáríves leltárazás, vakleltár; KTD, Intrastat bevallás\nelőkészítése</p></li>\n<li><p>Beszerzési árak idősoros nyilvántartása; boltok/telephelyek\ntöltése, áruk szétosztása</p></li>\n<li><p>Aktuális készlet cikkenként mennyiségben és értékben; korosított\nkészlet analitika</p></li>\n<li><p>Riportok lekérdezése Excelbe vagy PDF-be</p></li>\n</ul>\n<p><strong>Pénzügy</strong></p>\n<ul>\n<li><p>Forint és deviza pénztárak kezelése, váltópénz kezelése, pénztári\nidőszakok</p></li>\n<li><p>Utalási csomagok összeállítása, adatkapcsolat az elektronikus\nbanki terminálokkal</p></li>\n<li><p>Vevői, szállítói folyószámlák kezelése; forint és deviza\nbankszámlák; kompenzációk</p></li>\n<li><p>Kerekítések, árfolyamkülönbözetek, átértékelések\nkezelése</p></li>\n<li><p>Időszaki pénztárjelentés címletkezeléssel</p></li>\n<li><p>Pénzügyi levelezések: fizetési felszólítások, kompenzációs\nlevelek, késedelmi kamatlevelek, egyenlegközlők</p></li>\n<li><p>Kintlévőségek és szállítói tartozások összesítve; ÁFA riport;\nkorosított analitika</p></li>\n<li><p>Riportok lekérdezése Excelbe vagy PDF-be</p></li>\n</ul>\n<p><strong>Könyvelés</strong></p>\n<ul>\n<li><p>Adat importálási lehetőség szinte bármilyen rendszerből</p></li>\n<li><p>NAV online bekötés, kétirányú kommunikáció; automata adószám\nellenőrzés</p></li>\n<li><p>Könyvelési és analitikus időszakok segítségével zárható,\nnyitható, elkülöníthető ügyviteli folyamatok</p></li>\n<li><p>Automata kontírozások; kontírozott adatok átadása könyvelőprogram\nfelé</p></li>\n</ul>\n<p><strong>Szerviz</strong></p>\n<ul>\n<li><p>Korlátlan hibatípus lehetőség</p></li>\n<li><p>Munkalapra rögzíthető szerviz tevékenység, alkatrész</p></li>\n<li><p>Garanciális és fizetős tevékenység elkülönítése</p></li>\n<li><p>Árajánlatadás, e-mail elfogadással; egyedi azonosító kezelése;\nsablon munkalapok</p></li>\n<li><p>Munkalapból indítható számlázás</p></li>\n<li><p>Szerviz tevékenységekhez kapcsolódó dokumentumok (munkalap,\nátvételi jegyzőkönyv, garancialevél stb.)</p></li>\n<li><p>Riportok: átlagos szerviz intervallum, szerviz időtartam\nszervizesenként, összesített szervizjelentés</p></li>\n</ul>\n<p><strong>Szállítmányozás</strong></p>\n<ul>\n<li><p>Útvonaltervezés, fuvarfeladatok rögzítése, automata útdíj\nkalkuláció</p></li>\n<li><p>Visszaigazolás, megbízási szerződés automatikus elkészítése,\nkiküldése</p></li>\n<li><p>Flotta rendelkezésre állása; fuvarfeladatból indítható számlázás,\ntömeges számlázás</p></li>\n<li><p>Automatikus készletkönyvelés fuvarfeladatból</p></li>\n<li><p>Riportok: számlázási nyilvántartás, truck táblázat, rakott\nkilométer aránya</p></li>\n</ul>\n<p><strong>Flottakezelés</strong></p>\n<ul>\n<li><p>Gépjármű okmányok, szervizek nyilvántartása</p></li>\n<li><p>Kétféle üzemanyag-felhasználás kalkuláció NAV normáknak\nmegfelelően</p></li>\n<li><p>Útvonal nyilvántartás, e-menetlevél, gépjárműkövetés</p></li>\n</ul>\n<p><strong>Dokumentumkezelés</strong></p>\n<ul>\n<li><p>Szervezeti működéshez kapcsolódó dokumentumok, szerződések,\nmegrendelések, visszaigazolások tárolása</p></li>\n<li><p>Közvetlenül számlához kapcsolódó dokumentumok kezelése</p></li>\n<li><p>Dokumentum iktatás digitális iktatókönyvekbe</p></li>\n</ul>\n<p><strong>Engedélyezés</strong></p>\n<ul>\n<li><p>Teljes körű vezetői ellenőrzés, nyomon követés</p></li>\n<li><p>Egyedi engedélyezési protokollok kialakítása</p></li>\n<li><p>Többlépcsős jóváhagyó rendszer kiépítése</p></li>\n<li><p>Ügyviteli folyamatba integrált engedélyezések, akár\nfolyamatonként eltérő módon</p></li>\n<li><p>Költséghelyek, projektek kezelése; űrlapokhoz kapcsolódó\nmegjegyzések</p></li>\n</ul>\n<p><strong>HR</strong></p>\n<ul>\n<li><p>Munkavállalók kezelése, elektronikus munkaszerződés és módosítás\nkezelés</p></li>\n<li><p>Online szerződéskötés, bérszámfejtés előkészítés</p></li>\n<li><p>Online munkaügyi dokumentum nyilvántartás</p></li>\n<li><p>Műszak, munkarend, divízió, bérpótlék, munkavállalói juttatás\nnyilvántartás</p></li>\n<li><p>Digitalizált HR folyamatok</p></li>\n</ul>\n<p><strong>VIR – Vezető Információs Rendszer</strong></p>\n<ul>\n<li><p>Gazdálkodási adatok</p></li>\n<li><p>Cashflow riportok</p></li>\n<li><p>HR tervezés</p></li>\n<li><p>Fedezet riport</p></li>\n</ul>','Az Infinity moduláris felépítésű vállalatirányítási rendszer, ahol az egyes részterületek egymás közötti integrációjával a vállalat összes részlege egységes irányítási rendszerrel dolgozhat. Mivel web alapú szoftver, bárhonnan elérhető – használatához elegendő az internetkapcsolat. Működtethető személyi számítógépen, tableten és mobiltelefonon is. Működésének eredménye egy strukturált, naprakész információkkal rendelkező, hatékony irányítású vállalkozás, amely a lehető legrövidebb reakcióidő mellett működik. Főbb jellegzetességei modulonként: Adminisztráció Több telephely kezelése Korlátlan számú felhasználó Egyedi felhasználói jogosultságok beállítása Feladatkezelő modul Teljes testreszabhatóság Partnerkezelés Egységes törzsadat kezelés Felhasználó által definiált egyedi adatok nyilvántartása Friss, aktuális partner adatok bekérése Cégjelzőből CRM integrálása minden folyamathoz Online dokumentumkezelés, papírmentes iroda megoldások Munkarendek rögzítése, szabadságok kezelése, jelenléti ívek nyomtatása Google űrlapok létrehozása Automata e-mail kommunikáció ügyviteli folyamatba integráltan CRM Ügyfélminősítés egyedileg testreszabható szempontok alapján Automatizált, munkafolyamatokra építhető értékesítési folyamat Marketing kampányok megalapozása, segítése Ügyviteli folyamatba integrált feladatkiosztás Alkalmazottak munkaidejének rögzítése, feladathoz rendelése Hatékony ügyfélszolgálat UNAS webáruház kezelés Korlátlan számú webshop párhuzamos kezelése Árucikkek feltöltése Készletváltozás azonnali, automatikus frissítése Elektronikus számlázás egy gombnyomással, vagy automatikusan Értékesítés Árajánlat, megrendelés készítése, nyilvántartása, követése Árajánlatból megrendelés készítése, foglalások kezelése Több bizonylattömb; készlet alapú értékesítés (szállítólevéllel) és szolgáltatás számlák Egyedi vagy sablon alapú rögzítés Egyedi (gyári számos), sorozatszámos vonalkódok kezelése, vonalkód olvasó alkalmazhatósága Webes értékesítés integrálása, UNAS weboldal integrálás Vevőkártyák, utalványok, kuponok nyilvántartása, elfogadása Előlegbekérő vagy előlegszámla készítése, végszámlázás Fix vagy százalékos kedvezmény, egyedi árazási lehetőség nyugtánál és számlánál is Idegennyelvű számla kiállítás; bizonylatok rögzítése devizában, korlátlan devizaszám Kiegyenlítések kezelése devizában 6 alap bizonylati sablon, melyek mindegyike egyedi igényekhez alakítható Adóhatósági ellenőrzéshez adatszolgáltatás Értékesítési statisztikák időszakra, cikkcsoportra, outletre, értékesítőre szűrve Partnerek folyószámla kartonja, értékesítések fedezeti összesítője Riportok lekérdezése Excelbe vagy PDF-be Készletezés Testre szabható, egyedi felépítésű cikktörzs, fa szerkezetű cikkcsoport kódok Sorozatszám kezelés (egyedi vagy nem egyedi) Minimumkészlet, minimum árrés figyelés; kép feltöltése cikkhez, vonalkód nyomtatása Egyedi vagy tömeges (Excel alapú) cikk létrehozás, módosítás; termékvariánsok FIFO szerinti készletkezelés, tetszőleges számú telephely és raktár üzemeltetése Különböző tulajdonú készletek kezelése, webes foglalások kezelése RF adatgyűjtők, vonalkódolvasók – a manuális adatrögzítés kiküszöbölése Leltáríves leltárazás, vakleltár; KTD, Intrastat bevallás előkészítése Beszerzési árak idősoros nyilvántartása; boltok/telephelyek töltése, áruk szétoszt